using System.IO; using UnityEngine; using UnityEngine.SceneManagement; using UnityEngine.UI; namespace Reflectable { public sealed class ReflectableMenuController:MonoBehaviour { [SerializeField] GameObject continueButton,settingsPanel;[SerializeField] Text bestScore;[SerializeField] CanvasGroup group;string SavePath=>Path.Combine(Application.persistentDataPath,"reflectable_run.json");void Start(){if(continueButton)continueButton.SetActive(File.Exists(SavePath));if(bestScore)bestScore.text="BEST SCORE: "+PlayerPrefs.GetInt("ReflectableBest",0);if(group)StartCoroutine(Fade());}System.Collections.IEnumerator Fade(){group.alpha=0;for(float t=0;t<.5f;t+=Time.deltaTime){group.alpha=t/.5f;yield return null;}group.alpha=1;}public void NewGame(){SceneManager.LoadScene("Game");}public void Continue(){PlayerPrefs.SetInt("ReflectableContinue",1);SceneManager.LoadScene("Game");}public void ToggleSettings(){if(settingsPanel)settingsPanel.SetActive(!settingsPanel.activeSelf);}public void Quit(){Application.Quit();} } }
